CREATE TABLE report_fields_new (template_id TEXT NOT NULL CHECK (template_id IN ('service','attendance','external','internal','afericao','atend_presencial','atend_remoto','aval_cameras_fuga','aval_pista_pesagem','calibracao','cameras_fuga','checklist_calibracao','checklist_sist_pesagem','checklist_geral','manut_perifericos','manut_pista','pista_pesagem_precisao','rel_manut_balanca_aprb','rel_visita','sem_foros','sist_pesagem_precisao_geral')), id TEXT NOT NULL, label TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','textarea','date','number','select','attachment')), required INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL, options_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (template_id, id));
DROP TABLE report_fields;
ALTER TABLE report_fields_new RENAME TO report_fields;
CREATE INDEX IF NOT EXISTS report_fields_by_template ON report_fields (template_id, position);
